What does the third call return?
function* g() { yield 1; yield 2; }
const it = g();
it.next(); it.next();
it.next();

What does the last line log?
function* g() { const x = yield 1; yield x * 2; }
const it = g();
it.next();
console.log(it.next(5).value);

What does [...b()] return?
function* a() { yield 1; yield 2; }
function* b() { yield 0; yield* a(); yield 3; }

What does this log?
const o = Object.freeze({ inner: { v: 1 } });
o.inner.v = 2;
console.log(o.inner.v);

What does this log?
const a = { n: { v: 1 } };
const b = { ...a };
b.n.v = 2;
console.log(a.n.v);

What is the output order?
setTimeout(() => console.log("a"), 0);
Promise.resolve().then(() => console.log("b")).then(() => console.log("c"));
queueMicrotask(() => console.log("d"));

What is the output order?
async function f() { try { await Promise.reject(1); } finally { console.log("f"); } }
f().catch(() => console.log("c"));
console.log("s");

What is the output order?
const p = new Promise(r => setTimeout(() => r("x")));
p.then(v => console.log(v));
Promise.resolve().then(() => console.log("y"));
console.log("z");

What does this log?
function F() { this.x = 1; }
F.prototype.x = 2;
const f = new F();
delete f.x;
console.log(f.x);

What does this log?
function F() { return { a: 1 }; }
F.prototype.b = 2;
const f = new F();
console.log(f.b, f instanceof F);

What happens when this runs?
f();
var f = function () { console.log("x"); };

