What does this log?
const f = function g() { return typeof g; };
console.log(f(), typeof g);

What does this log?
function* g() { try { yield 1; } finally { console.log("cleanup"); } }
for (const v of g()) { break; }

What does this log?
function* g() { let i = 0; while (true) yield i++; }
const [a, , b] = g();
console.log(a, b);

What does the last line log?
function* g() { try { yield 1; } catch { yield "caught"; } }
const it = g();
it.next();
console.log(it.throw(new Error()).value);

